export function diagramMermaid(view) {
  const safe = value => value.replaceAll('"', "'");
  const rows = ['flowchart TB'];
  view.lanes.forEach((lane, row) => {
    rows.push(`  subgraph lane${row}["${safe(lane)}"]`);
    view.nodes.slice(row * 4, row * 4 + 4).forEach(n => rows.push(`    ${n.id}["${safe(n.title)}<br/>${safe(n.service)}"]`));
    rows.push('  end');
  });
  view.edges.forEach(([from,to,label,async]) => rows.push(`  ${from} ${async?'-.->':'-->'}|"${safe(label)}"| ${to}`));
  return rows.join('\n');
}
export function quickStartMarkdown(q, checked = []) {
  return `## ${q.id}: ${q.title}\n\nOwner: ${q.owner}\nEffort: ${q.effort} (indicative engineering effort, excludes approvals and procurement)\nDepends on: ${q.depends.join(', ') || 'None; start with discovery'}\n\nOutcome: ${q.outcome}\n\n### Prerequisites\n${q.prerequisites.map(x=>`- ${x}`).join('\n')}\n\n### Build sequence\n${q.steps.map((x,i)=>`${i+1}. ${x}`).join('\n')}\n\n### Acceptance evidence\n${q.acceptance.map((x,i)=>`- [${checked.includes(`${q.id}-${i}`)?'x':' '}] ${x}`).join('\n')}\n\n### Handover artefacts\n${q.artifacts.map(x=>`- ${x}`).join('\n')}\n\n### Rollback / stop conditions\n${q.rollback}\n\n### Starter contract: ${q.sample.filename}\nIllustrative design template, not deployable infrastructure. Replace placeholders and validate locally.\n\n\`\`\`${q.sample.language}\n${q.sample.content}\n\`\`\`\n\n### Official implementation references\n${q.sourceIds.map(i=>`- [${foundationSources[i][0]}](${foundationSources[i][1]})`).join('\n')}\n`;
}
export function organisationMermaid(model = 'lean') {
  const rows = ['flowchart TB', '  board["Executive leadership / risk committee"]', '  ciso["CISO / Head of Security"]', '  board --> ciso', '  audit["Independent internal audit"]', '  audit -.-> board', '  partners["Platform, application owners, HR, legal, procurement, MDR"]'];
  teams.forEach(team => {
    const allocation = (model === 'lean' ? team.lean : team.scaled).replaceAll('"', "'");
    rows.push(`  ${team.id}["${team.name}<br/>${team.lead}<br/>${allocation}"]`, `  ciso --> ${team.id}`, `  partners -.-> ${team.id}`);
  });
  return rows.join('\n');
}

export function blueprintMarkdown() {
  let checked = [];
  try { if (typeof window !== 'undefined') { const saved = JSON.parse(localStorage.getItem('slinn-foundation-evidence') || '[]'); if (Array.isArray(saved)) checked = saved; } } catch {}
  return `## Detailed architecture library\n\nProposed hybrid reference patterns; no AWS infrastructure is provisioned by this application. Validate regional availability, source support, cost and business requirements before implementation. Solid arrows denote control/request flows; dashed arrows denote asynchronous data/evidence flows.\n\n${architectureViews.map(v=>`### ${v.title}\n${v.summary}\nCapabilities: ${v.capabilities.join(', ')}\nFoundation recipes: ${v.quickStarts.join(', ')}\n\n\`\`\`mermaid\n${diagramMermaid(v)}\n\`\`\`\n\n${v.nodes.map(n=>`#### ${n.title} — ${n.service}\nOwner: ${n.owner}\n${n.detail}\nControl: ${n.control}`).join('\n\n')}\n\nDecisions:\n${v.decisions.map(x=>'- '+x).join('\n')}\nFailure tests:\n${v.failures.map(x=>'- '+x).join('\n')}\nAcceptance: ${v.acceptance}`).join('\n\n')}\n\n## Organisation & ownership\n\n\`\`\`mermaid\n${organisationMermaid()}\n\`\`\`\n\nProposed federated model: CISO accountable to executive leadership; five operating teams partner with enterprise platform, application/service owners, HR/IdP, legal/privacy, procurement and an independent audit function. Lean staffing is an illustrative starting allocation, not a staffed 24x7 SOC.\n\n${teams.map(t=>`### ${t.name}\nLead: ${t.lead}\nMission: ${t.mission}\nRoles: ${t.roles}\nLean model: ${t.lean}\nScaled model: ${t.scaled}\nCapabilities: ${t.capabilities.join(', ')}\nDeliverables: ${t.deliverables.join('; ')}\nInterface: ${t.interface}`).join('\n\n')}\n\n### RACI decision rights\n| Decision | Accountable | Responsible | Consulted | Informed |\n|---|---|---|---|---|\n${raci.map(r=>'| '+r.join(' | ')+' |').join('\n')}\n\n### 24x7 staffing calculation\nOne continuously staffed seat requires 168 coverage hours/week. At 37.5 contracted hours and 25% allowance for leave, training and other unavailability: 168 / (37.5 * 0.75) = 5.97 FTE (round up to 6 for a pooled model). This excludes team leadership, engineering and additional peak/incident capacity; actual shift and labour constraints require roster validation.\n\n## Delivery model\n\nOne product backlog, four delivery streams and named service/control owners. Times below are illustrative elapsed windows; quick-start effort is not an elapsed commitment.\n\n${deliveryStreams.map(d=>`### ${d.name}\nOwner: ${d.owner}\nIndicative window: ${d.start}\nInputs: ${d.inputs}\nWork: ${d.work}\nOutcome: ${d.outcomes}\nAcceptance gate: ${d.gate}\nDependencies: ${d.deps}`).join('\n\n')}\n\n### Delivery forums\n${deliveryCeremonies.map(r=>r.join(' | ')).join('\n')}\n\n### Service contracts\n${serviceContracts.map(([n,c,m])=>`- ${n}: ${c} Measures: ${m}`).join('\n')}\n\n### Definition of done\nNamed owner; versioned implementation and threat/risk assumptions; positive/negative/failure evidence; measured performance; least privilege; on-call/runbook; evidence retention; rollback and service acceptance. Emergency changes retain incident ownership and receive retrospective review.\n\n## Foundation quick starts\n\nThe checklists are planning/evidence tracking, not an assertion of deployed controls. Example contracts are templates, not production-ready IaC.\n\n${quickStarts.map(q=>quickStartMarkdown(q, checked)).join('\n\n')}`;
}
